"use client";

// The YB's service centre as a live 3D room instead of a painted backdrop.
// Everyone in it is a MakeHuman character (CC0, generated by the
// KawasanGodot / MandatAssets pipeline into public/office-cast/*.glb):
// the Personal Assistant beside the desk, an admin officer at the counter,
// an aide by the briefing board, and constituents waiting their turn.
// The page's hotspots are anchored to the objects they belong to.

import { Suspense, useEffect, useMemo, useRef, type ReactNode } from "react";
import { Canvas, useFrame, useThree } from "@react-three/fiber";
import { Html, useGLTF } from "@react-three/drei";
import * as THREE from "three";
import { clone as cloneSkinned } from "three/examples/jsm/utils/SkeletonUtils.js";

export type OfficeHotspot = { key: string; icon: string; title: string; onClick: () => void };

type Pose = "stand" | "sit" | "tablet" | "type";

const CAST = "/office-cast/";
// Spare decoders aren't fetched: these files only use meshopt.
const useCastModel = (name: string) => useGLTF(CAST + name + ".glb", false, true);

// ── posing ──────────────────────────────────────────────────────────
// MakeHuman exports in an A-pose with bone axes that differ per bone, so
// poses are set by aiming each bone at a world direction rather than by
// hand-tuned local Euler angles.
const _a = new THREE.Vector3();
const _b = new THREE.Vector3();
const _q = new THREE.Quaternion();
const _pq = new THREE.Quaternion();

function aim(bone: THREE.Object3D | undefined, child: THREE.Object3D | undefined, dir: THREE.Vector3) {
  if (!bone || !child) return;
  bone.updateWorldMatrix(true, true);
  bone.getWorldPosition(_a);
  child.getWorldPosition(_b);
  const cur = _b.sub(_a).normalize();
  _q.setFromUnitVectors(cur, dir.clone().normalize());
  const world = bone.getWorldQuaternion(new THREE.Quaternion());
  world.premultiply(_q);
  bone.parent?.getWorldQuaternion(_pq);
  bone.quaternion.copy(_pq.invert().multiply(world));
  bone.updateWorldMatrix(false, true);
}

function applyPose(root: THREE.Object3D, pose: Pose) {
  const b = (n: string) => root.getObjectByName(n);
  const v = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
  // the character faces +z in its own space; all directions are in that frame
  root.updateWorldMatrix(true, true);
  const local = (d: THREE.Vector3) => d.applyQuaternion(root.getWorldQuaternion(new THREE.Quaternion()));
  for (const s of [1, -1]) {
    const side = s === 1 ? "l" : "r";
    // A-pose arms down to the sides
    aim(b(`upperarm_${side}`), b(`lowerarm_${side}`), local(v(0.12 * s, -1, 0.02)));
    aim(b(`lowerarm_${side}`), b(`hand_${side}`), local(v(0.05 * s, -1, 0.18)));
  }
  if (pose === "sit" || pose === "type") {
    for (const side of ["l", "r"]) {
      aim(b(`thigh_${side}`), b(`calf_${side}`), local(v(0, -0.08, 1)));
      aim(b(`calf_${side}`), b(`foot_${side}`), local(v(0, -1, 0.08)));
    }
    for (const s of [1, -1]) {
      const side = s === 1 ? "l" : "r";
      if (pose === "type") {
        aim(b(`upperarm_${side}`), b(`lowerarm_${side}`), local(v(0.1 * s, -0.75, 0.6)));
        aim(b(`lowerarm_${side}`), b(`hand_${side}`), local(v(-0.1 * s, -0.1, 1)));
      } else {
        // hands resting on the lap
        aim(b(`upperarm_${side}`), b(`lowerarm_${side}`), local(v(0.04 * s, -0.95, 0.28)));
        aim(b(`lowerarm_${side}`), b(`hand_${side}`), local(v(-0.12 * s, -0.55, 0.85)));
      }
    }
  }
  if (pose === "tablet") {
    // right forearm forward holding the tablet, left hand supporting it
    aim(b("upperarm_r"), b("lowerarm_r"), local(v(-0.1, -1, 0.15)));
    aim(b("lowerarm_r"), b("hand_r"), local(v(0.25, -0.1, 1)));
    aim(b("upperarm_l"), b("lowerarm_l"), local(v(0.1, -1, 0.2)));
    aim(b("lowerarm_l"), b("hand_l"), local(v(-0.45, -0.05, 1)));
  }
}

function Person({ name, pose, position, rotation = 0, onClick, label }: {
  name: string;
  pose: Pose;
  position: [number, number, number];
  rotation?: number;
  onClick?: () => void;
  label?: ReactNode;
}) {
  const gltf = useCastModel(name);
  const scene = useMemo(() => {
    const s = cloneSkinned(gltf.scene);
    s.traverse((o) => {
      const m = o as THREE.Mesh;
      if (m.isMesh) {
        m.castShadow = true;
        m.receiveShadow = true;
        m.frustumCulled = false;
      }
    });
    return s;
  }, [gltf.scene]);
  const group = useRef<THREE.Group>(null);
  const spine = useRef<THREE.Object3D>();
  const head = useRef<THREE.Object3D>();
  const base = useRef<THREE.Quaternion[]>([]);
  const phase = useMemo(() => Math.random() * 10, []);

  useEffect(() => {
    if (!group.current) return;
    applyPose(scene, pose);
    // seated: drop the body so the pelvis rests on a 0.47 m seat
    if (pose === "sit" || pose === "type") {
      scene.updateWorldMatrix(true, true);
      const pelvis = scene.getObjectByName("pelvis");
      const p = pelvis ? pelvis.getWorldPosition(new THREE.Vector3()) : new THREE.Vector3();
      const groupY = group.current.getWorldPosition(new THREE.Vector3()).y;
      scene.position.y = 0.47 - (p.y - groupY) + 0.08;
      scene.position.z = -0.18;
    }
    spine.current = scene.getObjectByName("spine_02");
    head.current = scene.getObjectByName("head");
    base.current = [spine.current?.quaternion.clone() ?? new THREE.Quaternion(), head.current?.quaternion.clone() ?? new THREE.Quaternion()];
  }, [scene, pose]);

  // idle life: slow breathing and a slight head turn
  useFrame(({ clock }) => {
    const t = clock.elapsedTime + phase;
    if (spine.current && base.current[0]) {
      spine.current.quaternion.copy(base.current[0]).multiply(_q.setFromAxisAngle(_a.set(1, 0, 0), Math.sin(t * 1.4) * 0.012));
    }
    if (head.current && base.current[1]) {
      head.current.quaternion.copy(base.current[1]).multiply(_q.setFromAxisAngle(_a.set(0, 1, 0), Math.sin(t * 0.35) * 0.18));
    }
  });

  return (
    <group ref={group} position={position} rotation={[0, rotation, 0]}
      onClick={onClick ? (e) => { e.stopPropagation(); onClick(); } : undefined}
      onPointerOver={onClick ? () => { document.body.style.cursor = "pointer"; } : undefined}
      onPointerOut={onClick ? () => { document.body.style.cursor = ""; } : undefined}>
      <primitive object={scene} />
      {pose === "tablet" && (
        <mesh position={[0.06, 1.0, 0.36]} rotation={[-0.9, 0, 0]} castShadow>
          <boxGeometry args={[0.26, 0.18, 0.012]} />
          <meshStandardMaterial color="#1b2430" metalness={0.4} roughness={0.3} emissive="#2ba6d8" emissiveIntensity={0.25} />
        </mesh>
      )}
      {label}
    </group>
  );
}

// ── furniture ───────────────────────────────────────────────────────
function Box({ size, position, color, rotation, emissive, ...rest }: {
  size: [number, number, number]; position: [number, number, number]; color: string;
  rotation?: [number, number, number]; emissive?: string; roughness?: number; metalness?: number;
}) {
  return (
    <mesh position={position} rotation={rotation} castShadow receiveShadow>
      <boxGeometry args={size} />
      <meshStandardMaterial color={color} emissive={emissive ?? "#000"} emissiveIntensity={emissive ? 0.9 : 0}
        roughness={rest.roughness ?? 0.7} metalness={rest.metalness ?? 0.05} />
    </mesh>
  );
}

function Chair({ position, rotation = 0, color = "#1f2933" }: { position: [number, number, number]; rotation?: number; color?: string }) {
  return (
    <group position={position} rotation={[0, rotation, 0]}>
      <Box size={[0.5, 0.08, 0.5]} position={[0, 0.45, 0]} color={color} />
      <Box size={[0.5, 0.55, 0.07]} position={[0, 0.76, -0.24]} color={color} />
      <Box size={[0.05, 0.45, 0.05]} position={[0, 0.22, 0]} color="#555d66" metalness={0.6} />
      <Box size={[0.42, 0.04, 0.42]} position={[0, 0.02, 0]} color="#555d66" metalness={0.6} />
    </group>
  );
}

function Sofa({ position, rotation = 0 }: { position: [number, number, number]; rotation?: number }) {
  const c = "#3c4a5a";
  return (
    <group position={position} rotation={[0, rotation, 0]}>
      <Box size={[2.0, 0.42, 0.8]} position={[0, 0.21, 0]} color={c} />
      <Box size={[2.0, 0.5, 0.18]} position={[0, 0.64, -0.31]} color={c} />
      <Box size={[0.18, 0.62, 0.8]} position={[-0.95, 0.31, 0]} color={c} />
      <Box size={[0.18, 0.62, 0.8]} position={[0.95, 0.31, 0]} color={c} />
    </group>
  );
}

function Plant({ position }: { position: [number, number, number] }) {
  return (
    <group position={position}>
      <mesh position={[0, 0.2, 0]} castShadow><cylinderGeometry args={[0.18, 0.14, 0.4, 12]} /><meshStandardMaterial color="#d8d2c4" /></mesh>
      {[0, 1, 2, 3, 4].map((i) => (
        <mesh key={i} position={[Math.sin(i * 1.3) * 0.12, 0.75 + i * 0.12, Math.cos(i * 1.3) * 0.12]} castShadow>
          <sphereGeometry args={[0.22 - i * 0.02, 10, 8]} /><meshStandardMaterial color={i % 2 ? "#3f7a3a" : "#2f6430"} />
        </mesh>
      ))}
    </group>
  );
}

function Flag({ position }: { position: [number, number, number] }) {
  // Jalur Gemilang, kept simple: stripes, canton, crescent and star suggestion
  return (
    <group position={position}>
      <mesh position={[0, 1.15, 0]} castShadow><cylinderGeometry args={[0.025, 0.025, 2.3, 8]} /><meshStandardMaterial color="#c9b26a" metalness={0.7} roughness={0.3} /></mesh>
      <group position={[0.42, 1.95, 0]}>
        {Array.from({ length: 7 }, (_, i) => (
          <Box key={i} size={[0.8, 0.057, 0.01]} position={[0, 0.17 - i * 0.057, 0]} color={i % 2 ? "#ffffff" : "#cc0001"} />
        ))}
        <Box size={[0.4, 0.23, 0.012]} position={[-0.2, 0.085, 0.002]} color="#010066" />
        <mesh position={[-0.24, 0.085, 0.01]}><circleGeometry args={[0.07, 16]} /><meshBasicMaterial color="#ffcc00" /></mesh>
        <mesh position={[-0.22, 0.085, 0.011]}><circleGeometry args={[0.06, 16]} /><meshBasicMaterial color="#010066" /></mesh>
        <mesh position={[-0.12, 0.085, 0.011]}><circleGeometry args={[0.04, 14]} /><meshBasicMaterial color="#ffcc00" /></mesh>
      </group>
    </group>
  );
}

function Hotspot({ spot, position }: { spot?: OfficeHotspot; position: [number, number, number] }) {
  if (!spot) return null;
  return (
    <Html position={position} center zIndexRange={[20, 10]}>
      <button type="button" onClick={spot.onClick} aria-label={spot.title} title={spot.title}
        className="office-hotspot flex items-center gap-2 whitespace-nowrap border px-3 py-2 text-[10px] font-black tracking-wide text-white shadow-xl transition hover:border-gold"
        style={{ borderColor: "rgb(var(--cyan-rgb) / .58)", background: "rgb(2 8 20 / .88)", fontFamily: "'Space Mono', monospace" }}>
        <span className="relative flex h-2.5 w-2.5"><i className="absolute inset-0 animate-ping rounded-full bg-cyan/70" /><i className="relative m-auto h-2 w-2 rounded-full bg-cyan" /></span>
        <span aria-hidden>{spot.icon}</span><span className="office-hotspot__label">{spot.title}</span>
      </button>
    </Html>
  );
}

// ── room ────────────────────────────────────────────────────────────
function Room({ rural, night }: { rural: boolean; night: boolean }) {
  const wall = rural ? "#c8b089" : "#d9dde2";
  const floor = rural ? "#7a5a3c" : "#8a8f96";
  const W = 9, D = 7, H = 3.3;
  return (
    <group>
      <mesh rotation={[-Math.PI / 2, 0, 0]} receiveShadow><planeGeometry args={[W, D]} /><meshStandardMaterial color={floor} roughness={0.85} /></mesh>
      <mesh position={[0, 0.006, 0.4]} rotation={[-Math.PI / 2, 0, 0]} receiveShadow><planeGeometry args={[3.6, 2.4]} /><meshStandardMaterial color="#5a2f2f" roughness={1} /></mesh>
      {/* back wall with window band */}
      <Box size={[W, 0.9, 0.12]} position={[0, 0.45, -D / 2]} color={wall} />
      <Box size={[W, 0.5, 0.12]} position={[0, H - 0.25, -D / 2]} color={wall} />
      <mesh position={[0, 1.95, -D / 2 - 0.05]}>
        <planeGeometry args={[W, 2.1]} />
        <meshBasicMaterial color={night ? "#0b1530" : "#a9cbe6"} />
      </mesh>
      {/* skyline seen through the glass */}
      {Array.from({ length: 16 }, (_, i) => {
        const h = 0.4 + ((i * 37) % 11) / 11 * 1.3;
        return <mesh key={i} position={[-4.3 + i * 0.57, 0.95 + h / 2, -D / 2 - 0.6]}>
          <boxGeometry args={[0.45, h, 0.2]} />
          <meshBasicMaterial color={night ? (i % 3 ? "#1c2a48" : "#2c3b5c") : (i % 3 ? "#7f9cb5" : "#93acc0")} />
        </mesh>;
      })}
      {Array.from({ length: 9 }, (_, i) => <Box key={i} size={[0.06, 2.1, 0.08]} position={[-4.5 + i * 1.125, 1.95, -D / 2 + 0.02]} color="#3a4048" metalness={0.5} />)}
      {/* side walls */}
      <Box size={[0.12, H, D]} position={[-W / 2, H / 2, 0]} color={wall} />
      <Box size={[0.12, H, D]} position={[W / 2, H / 2, 0]} color={wall} />
      <mesh position={[0, H, 0]} rotation={[Math.PI / 2, 0, 0]}><planeGeometry args={[W, D]} /><meshBasicMaterial color={night ? "#3a3f48" : "#e8eaec"} /></mesh>
      {/* ceiling light panels */}
      {[-2.5, 0, 2.5].map((x) => <Box key={x} size={[1.2, 0.03, 0.5]} position={[x, H - 0.06, 0]} color="#ffffff" emissive="#fff6e0" />)}
      {/* accent strip in the party-room cyan/gold */}
      <Box size={[W - 0.2, 0.05, 0.02]} position={[0, 0.92, -D / 2 + 0.07]} color="#0aa7c9" emissive="#0aa7c9" />
    </group>
  );
}

function CameraFit() {
  const { camera, size } = useThree();
  useEffect(() => {
    const cam = camera as THREE.PerspectiveCamera;
    const portrait = size.height > size.width;
    // portrait phones: closer and lower, aimed at the desk and the PA so
    // the people fill the screen instead of ceiling and empty floor
    cam.fov = portrait ? 56 : 42;
    cam.position.set(portrait ? 0.9 : 0.6, portrait ? 1.75 : 2.3, portrait ? 4.6 : 5.6);
    cam.lookAt(portrait ? 0.6 : 0, portrait ? 1.15 : 1.05, -1.2);
    cam.updateProjectionMatrix();
  }, [camera, size.width, size.height]);
  return null;
}

export default function Office3D({ assistantName, rural, night, hotspots, onAssistant, assistantLabel }: {
  assistantName: "pa_male" | "pa_female";
  rural: boolean;
  night: boolean;
  hotspots: Partial<Record<"desk" | "schedule" | "news" | "files", OfficeHotspot>>;
  onAssistant: () => void;
  assistantLabel: string;
}) {
  return (
    <Canvas shadows dpr={[1, 1.75]} camera={{ fov: 42, near: 0.1, far: 60 }} gl={{ antialias: true }}
      onCreated={({ gl }) => { gl.toneMapping = THREE.ACESFilmicToneMapping; gl.toneMappingExposure = night ? 0.95 : 1.05; }}>
      <CameraFit />
      <color attach="background" args={[night ? "#060b18" : "#cfe0ee"]} />
      <hemisphereLight args={[night ? "#7d8db5" : "#ffffff", "#5a4a3a", night ? 0.6 : 0.9]} />
      <directionalLight position={[2, 6, 5]} intensity={night ? 0.9 : 1.6} castShadow shadow-mapSize={[1024, 1024]}
        shadow-camera-left={-6} shadow-camera-right={6} shadow-camera-top={6} shadow-camera-bottom={-6} shadow-bias={-0.0005} />
      <pointLight position={[0, 3, 0.5]} intensity={night ? 12 : 4} color="#ffe7c2" distance={9} />
      <Room rural={rural} night={night} />

      {/* YB's desk with monitor: Strategy Desk */}
      <group position={[0, 0, -1.5]}>
        <Box size={[2.2, 0.06, 1.0]} position={[0, 0.76, 0]} color={rural ? "#6b4a2e" : "#4a3524"} roughness={0.5} />
        <Box size={[2.2, 0.72, 0.06]} position={[0, 0.38, -0.45]} color={rural ? "#5c3f27" : "#3b2a1c"} />
        <Box size={[0.06, 0.72, 0.9]} position={[-1.07, 0.38, 0]} color="#3b2a1c" />
        <Box size={[0.06, 0.72, 0.9]} position={[1.07, 0.38, 0]} color="#3b2a1c" />
        <Box size={[0.62, 0.38, 0.03]} position={[0.3, 1.12, -0.2]} color="#11161d" emissive="#123a52" metalness={0.3} />
        <Box size={[0.06, 0.18, 0.06]} position={[0.3, 0.88, -0.22]} color="#2b3038" />
        <Box size={[0.3, 0.02, 0.22]} position={[-0.5, 0.8, 0.1]} color="#f4f1e8" />
        <Box size={[0.24, 0.01, 0.16]} position={[-0.15, 0.795, 0.15]} color="#e8e1cf" rotation={[0, 0.3, 0]} />
        <Chair position={[0, 0, -0.95]} rotation={0} color="#2a2018" />
        <Chair position={[-0.45, 0, 0.75]} rotation={Math.PI} />
        <Chair position={[0.45, 0, 0.75]} rotation={Math.PI} />
      </group>
      <Hotspot spot={hotspots.desk} position={[0.3, 1.55, -1.7]} />

      {/* briefing / schedule board */}
      <group position={[-1.6, 0, -3.35]}>
        <Box size={[1.6, 1.0, 0.04]} position={[0, 1.7, 0]} color="#f7f7f2" />
        {Array.from({ length: 12 }, (_, i) => <Box key={i} size={[0.22, 0.16, 0.01]} position={[-0.6 + (i % 6) * 0.24, 1.88 - Math.floor(i / 6) * 0.3, 0.025]} color={["#f5d76e", "#a8d8f0", "#f2a7a0"][i % 3]} />)}
      </group>
      <Hotspot spot={hotspots.schedule} position={[-1.6, 2.35, -3.3]} />

      {/* wall TV with the news */}
      <group position={[1.9, 0, -3.36]}>
        <Box size={[1.5, 0.86, 0.05]} position={[0, 1.95, 0]} color="#0a0d12" metalness={0.4} />
        <mesh position={[0, 1.95, 0.03]}><planeGeometry args={[1.4, 0.78]} /><meshBasicMaterial color={night ? "#1e5a8a" : "#2a74a8"} /></mesh>
        <Box size={[1.4, 0.12, 0.01]} position={[0, 1.62, 0.035]} color="#c0392b" emissive="#c0392b" />
      </group>
      <Hotspot spot={hotspots.news} position={[1.9, 2.55, -3.3]} />

      {/* constituency files: cabinets along the left wall */}
      <group position={[-4.15, 0, -1.4]}>
        {[0, 0.62, 1.24].map((z) => (
          <group key={z} position={[0, 0, z]}>
            <Box size={[0.6, 1.35, 0.58]} position={[0, 0.675, 0]} color="#7d8791" metalness={0.5} roughness={0.4} />
            {[0.3, 0.7, 1.1].map((y) => <Box key={y} size={[0.02, 0.05, 0.3]} position={[0.31, y, 0]} color="#cfd5db" metalness={0.8} />)}
          </group>
        ))}
        <Box size={[0.3, 0.25, 0.4]} position={[0, 1.48, 0.62]} color="#c8a46a" />
      </group>
      <Hotspot spot={hotspots.files} position={[-4.0, 1.8, -0.8]} />

      <Flag position={[-1.3, 0, -2.6]} />
      <Plant position={[3.9, 0, -3.0]} />
      <Plant position={[-3.9, 0, -3.0]} />
      <Plant position={[3.9, 0, 2.2]} />

      {/* reception counter, front left */}
      <group position={[-3.0, 0, 1.2]} rotation={[0, Math.PI / 2, 0]}>
        <Box size={[1.8, 1.05, 0.5]} position={[0, 0.525, 0.3]} color={rural ? "#8a6a48" : "#e9e6df"} />
        <Box size={[1.8, 0.04, 0.7]} position={[0, 0.76, -0.1]} color="#cdbb98" />
        <Box size={[0.5, 0.32, 0.03]} position={[0.2, 0.98, -0.2]} color="#11161d" emissive="#123a52" />
        <Chair position={[0.2, 0, -0.65]} rotation={0} />
      </group>

      {/* waiting area, front right */}
      <Sofa position={[3.0, 0, 0.9]} rotation={-Math.PI / 2} />
      <Box size={[0.6, 0.4, 0.6]} position={[2.15, 0.2, 0.9]} color="#6b4a2e" />

      <Suspense fallback={null}>
        <Person name={assistantName} pose="tablet" position={[1.45, 0, -0.9]} rotation={-0.55} onClick={onAssistant}
          label={<Html position={[0, 0.12, 0.35]} center zIndexRange={[20, 10]}>
            <button type="button" onClick={onAssistant} className="office-hotspot whitespace-nowrap border px-3 py-1.5 text-[9px] font-black tracking-widest text-gold shadow-xl"
              style={{ borderColor: "rgb(var(--gold-rgb) / .65)", background: "rgb(2 8 20 / .9)", fontFamily: "'Space Mono', monospace" }}
              aria-label={assistantLabel}>✦ <span className="office-hotspot__label">{assistantLabel}</span></button>
          </Html>} />
        {/* behind the counter, facing the room */}
        <Person name="admin" pose="type" position={[-3.65, 0, 1.0]} rotation={Math.PI / 2} />
        <Person name="aide" pose="stand" position={[-0.6, 0, -2.75]} rotation={0.35} />
        <Person name="makcik" pose="sit" position={[3.0, 0, 0.45]} rotation={-Math.PI / 2} />
        <Person name="pakcik" pose="sit" position={[3.0, 0, 1.35]} rotation={-Math.PI / 2} />
        {/* waiting their turn: one at the counter talking to the admin, one by the sofa */}
        <Person name="uncle" pose="stand" position={[2.1, 0, -0.35]} rotation={-0.95} />
        <Person name="anak_muda" pose="stand" position={[-1.75, 0, 1.15]} rotation={-Math.PI / 2 - 0.35} />
      </Suspense>
    </Canvas>
  );
}

["pa_male", "pa_female", "admin", "aide", "makcik", "pakcik", "uncle", "anak_muda"].forEach((n) => useGLTF.preload(CAST + n + ".glb", false, true));
